#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <mmsystem.h>
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <thread>

namespace {
struct TimerProbe {
    bool enabled = false;
    TimerProbe() {
        const char* setting = std::getenv("STRATA_TIMER_RESOLUTION");
        enabled = setting && setting[0] == '1';
        if (enabled && timeBeginPeriod(1) != TIMERR_NOERROR) std::abort();
        std::array<double, 9> samples;
        for (auto& sample : samples) {
            const auto start = std::chrono::steady_clock::now();
            std::this_thread::sleep_for(std::chrono::microseconds(25));
            sample = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
        }
        std::sort(samples.begin(), samples.end());
        std::fprintf(stderr, "TIMER_PROBE period_1ms=%d requested_us=25 min_ms=%.6f median_ms=%.6f max_ms=%.6f\n",
                     enabled, samples.front(), samples[4], samples.back());
    }
    ~TimerProbe() { if (enabled) timeEndPeriod(1); }
} timer_probe;
}
